27: static void http_cb(struct mg_connection *c, int ev, void *ev_data) {
28:   if (ev == MG_EV_READ || ev == MG_EV_CLOSE ||
29:       (ev == MG_EV_POLL && c->is_accepted && !c->is_draining &&
30:        c->recv.len > 0)) {  // see #2796
31:     struct mg_http_message hm;
32:     size_t ofs = 0;  // Parsing offset
33:     while (c->is_resp == 0 && ofs < c->recv.len) {
34:       const char *buf = (char *) c->recv.buf + ofs;
35:       int n = mg_http_parse(buf, c->recv.len - ofs, &hm);
36:       struct mg_str *te;  // Transfer - encoding header
37:       bool is_chunked = false, is_http_1_0 = false;
38:       size_t old_len = c->recv.len;
39:       if (n < 0) {
40:         // We don't use mg_error() here, to avoid closing pipelined requests
41:         // prematurely, see #2592
42:         MG_ERROR(("HTTP parse, %lu bytes", c->recv.len));
43:         c->is_draining = 1;
44:         mg_hexdump(buf, c->recv.len - ofs > 16 ? 16 : c->recv.len - ofs);
45:         c->recv.len = 0;
46:         return;
47:       }
48:       if (n == 0) break;                 // Request is not buffered yet
49:       mg_call(c, MG_EV_HTTP_HDRS, &hm);  // Got all HTTP headers
50:       if (c->recv.len != old_len) {
51:         // User manipulated received data. Wash our hands
52:         MG_DEBUG(("%lu detaching HTTP handler", c->id));
53:         c->pfn = NULL;
54:         return;
55:       }
56:       if (ev == MG_EV_CLOSE) {  // If client did not set Content-Length
57:         hm.message.len = c->recv.len - ofs;  // and closes now, deliver MSG
58:         hm.body.len = hm.message.len - (size_t) (hm.body.buf - hm.message.buf);
59:       }
60:       is_http_1_0 =
61:           hm.proto.len > 8 && mg_ncasecmp(hm.proto.buf, "HTTP/1.0", 8) == 0;
62:       // HTTP/1.0 does not use "Transfer-Encoding: chunked"
63:       if (!is_http_1_0 &&
64:           (te = mg_http_get_header(&hm, "Transfer-Encoding")) != NULL) {
65:         if (mg_strcasecmp(*te, mg_str("chunked")) == 0) {
66:           is_chunked = true;
67:         } else {
68:           mg_error(c, "Invalid Transfer-Encoding");  // See #2460
69:           return;
70:         }
71:       } else if (mg_http_get_header(&hm, "Content-length") == NULL) {
72:         // #2593: HTTP packets must contain either Transfer-Encoding or
73:         // Content-length
74:         bool is_response = mg_ncasecmp(hm.method.buf, "HTTP/", 5) == 0;
75:         bool require_content_len = false;
76:         if (!is_response && (mg_strcasecmp(hm.method, mg_str("POST")) == 0 ||
77:                              mg_strcasecmp(hm.method, mg_str("PUT")) == 0)) {
78:           // POST and PUT should include an entity body. Therefore, they should
79:           // contain a Content-length header (unless the body length is 0, in
80:           // which case it can be omitted). Other requests can also contain a
81:           // body, but their content has no defined semantics (RFC 7231)
82:           if (hm.body.len != 0) require_content_len = true;
83:           ofs += (size_t) n;  // this request has been processed
84:         } else if (is_response) {
85:           // HTTP spec 7.2 Entity body: All other responses must include a body
86:           // or Content-Length header field defined with a value of 0.
87:           int status = mg_http_status(&hm);
88:           require_content_len = status >= 200 && status != 204 && status != 304;
89:         }
90:         if (require_content_len) {
91:           if (!c->is_client) mg_http_reply(c, 411, "", "");
92:           MG_ERROR(("Content length missing from %s",
93:                     is_response ? "response" : "request"));
94:         }
95:       }
96: 
97:       if (is_chunked) {
98:         // For chunked data, strip off prefixes and suffixes from chunks
99:         // and relocate them right after the headers, then report a message
100:         char *s = (char *) c->recv.buf + ofs + n;
101:         int o = 0, pl, dl, cl, len = (int) (c->recv.len - ofs - (size_t) n);
102: 
103:         // Find zero-length chunk (the end of the body)
104:         while ((cl = skip_chunk(s + o, len - o, &pl, &dl)) > 0 && dl) o += cl;
105:         if (cl == 0) break;  // No zero-len chunk, buffer more data
106:         if (cl < 0) {
107:           mg_error(c, "Invalid chunk");
108:           break;
109:         }
110: 
111:         // Zero chunk found. Second pass: strip + relocate
112:         o = 0, hm.body.len = 0, hm.message.len = (size_t) n;
113:         while ((cl = skip_chunk(s + o, len - o, &pl, &dl)) > 0) {
114:           memmove(s + hm.body.len, s + o + pl, (size_t) dl);
115:           o += cl, hm.body.len += (size_t) dl, hm.message.len += (size_t) dl;
116:           if (dl == 0) break;
117:         }
118:         ofs += (size_t) (n + o);
119:       } else {  // Normal, non-chunked data
120:         size_t len = c->recv.len - ofs - (size_t) n;
121:         if (hm.body.len > len) break;  // Buffer more data
122:         ofs += (size_t) n + hm.body.len;
123:       }
124: 
125:       if (c->is_accepted) c->is_resp = 1;  // Start generating response
126:       mg_call(c, MG_EV_HTTP_MSG, &hm);     // User handler can clear is_resp
127:       if (c->is_accepted && !c->is_resp) {
128:         struct mg_str *cc = mg_http_get_header(&hm, "Connection");
129:         if (cc != NULL && mg_strcasecmp(*cc, mg_str("close")) == 0) {
130:           c->is_draining = 1;  // honor "Connection: close"
131:           break;
132:         }
133:       }
134:     }
135:     if (ofs > 0) mg_iobuf_del(&c->recv, 0, ofs);  // Delete processed data
136:   }

